import { Controller, Delete, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 반려 사유 누락은 422 REJECT_REASON_REQUIRED로 거절한다.
// 가정: 알림 채널은 기본 채널 '포털'로 보낸다.
const DEFAULT_CHANNEL = '포털';
const ID_PATTERN = /^[0-9]+$/;

function pathId(value: unknown): string {
  const text = typeof value === 'string' ? value : '';
  if (!ID_PATTERN.test(text)) {
    throw new ApiError(404, 'EDUCATION_APPLICATION_NOT_FOUND', '교육신청을 찾을 수 없습니다.');
  }
  return text;
}

@Controller('api/v1')
export class FnSfr01503Controller {
  @Post('/education-applications')
  @HttpCode(200)
  async createEducationApplication(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const rawSession = data['educationSessionId'];
    if (rawSession === undefined || rawSession === null || !ID_PATTERN.test(String(rawSession))) {
      throw new ApiError(400, 'VALIDATION_FAILED', '교육차수를 선택해 주세요.');
    }
    const rawReason = data['applicationReason'];
    if (rawReason !== undefined && rawReason !== null && typeof rawReason !== 'string') {
      throw new ApiError(400, 'VALIDATION_FAILED', '신청 사유는 글자로 입력해 주세요.');
    }
    const reason = typeof rawReason === 'string' && rawReason.trim() !== '' ? rawReason : null;
    return transaction(async (db) => {
      const sessions = await db.query(
        'SELECT education_session_id FROM education_session WHERE education_session_id = CAST(:sessionId AS bigint)',
        { sessionId: String(rawSession) },
      );
      if (sessions.length === 0) {
        throw new ApiError(404, 'EDUCATION_SESSION_NOT_FOUND', '교육 차수를 찾을 수 없습니다.');
      }
      const duplicated = await db.query(
        `SELECT education_application_id FROM education_application
         WHERE education_session_id = CAST(:sessionId AS bigint)
           AND employee_id = CAST(:userId AS bigint)`,
        { sessionId: String(rawSession), userId: user.id },
      );
      if (duplicated.length > 0) {
        throw new ApiError(409, 'EDUCATION_APPLICATION_DUPLICATED', '이미 같은 차수에 신청하셨습니다.');
      }
      const rows = await db.query(
        `INSERT INTO education_application
           (education_session_id, employee_id, status, application_reason, created_at, updated_at)
         VALUES
           (CAST(:sessionId AS bigint), CAST(:userId AS bigint), '신청', :reason, now(), now())
         RETURNING education_application_id AS "educationApplicationId", status AS "status"`,
        { sessionId: String(rawSession), userId: user.id, reason },
      );
      // TODO: 승인권자 알림은 승인권자를 정하는 출처가 입력에 없어 보내지 않는다.
      return rows[0];
    });
  }

  @Post('/education-applications/:educationApplicationId/approve')
  @HttpCode(200)
  async approveEducationApplication(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자');
    const id = pathId(req.params['educationApplicationId']);
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT education_session_id AS "sessionId", employee_id AS "employeeId", status AS "status"
         FROM education_application
         WHERE education_application_id = CAST(:id AS bigint)
         FOR UPDATE`,
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'EDUCATION_APPLICATION_NOT_FOUND', '교육신청을 찾을 수 없습니다.');
      }
      const current = found[0];
      if (current.status !== '신청') {
        throw new ApiError(409, 'EDUCATION_APPLICATION_STATE_CONFLICT', '신청 상태인 건만 승인할 수 있습니다.');
      }
      const rows = await db.query(
        `UPDATE education_application
         SET status = '승인', updated_at = now()
         WHERE education_application_id = CAST(:id AS bigint)
         RETURNING education_application_id AS "educationApplicationId", status AS "status"`,
        { id },
      );
      await db.execute(
        `INSERT INTO education_attendee (education_session_id, employee_id, created_at, updated_at)
         VALUES (CAST(:sessionId AS bigint), CAST(:employeeId AS bigint), now(), now())
         ON CONFLICT (education_session_id, employee_id) DO NOTHING`,
        { sessionId: String(current.sessionId), employeeId: String(current.employeeId) },
      );
      await db.execute(
        `INSERT INTO notification
           (recipient_id, channel, title, content, read_status, event_type, target_type, target_id, created_at, updated_at)
         VALUES
           (CAST(:recipientId AS bigint), :channel, :title, :content, '안읽음', 'EDUCATION_APPLICATION_APPROVED',
            'EDUCATION_APPLICATION', CAST(:id AS bigint), now(), now())`,
        {
          recipientId: String(current.employeeId),
          channel: DEFAULT_CHANNEL,
          title: '교육신청이 승인되었습니다.',
          content: '신청하신 교육이 승인되어 교육대상자로 반영되었습니다.',
          id,
        },
      );
      return rows[0];
    });
  }

  @Post('/education-applications/:educationApplicationId/reject')
  @HttpCode(200)
  async rejectEducationApplication(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자');
    const id = pathId(req.params['educationApplicationId']);
    const data = checks.inputOf(req.body);
    const rawReason = data['rejectReason'];
    if (rawReason !== undefined && rawReason !== null && typeof rawReason !== 'string') {
      throw new ApiError(400, 'VALIDATION_FAILED', '반려 사유는 글자로 입력해 주세요.');
    }
    if (typeof rawReason !== 'string' || rawReason.trim() === '') {
      throw new ApiError(422, 'REJECT_REASON_REQUIRED', '반려 사유를 입력해 주세요.');
    }
    const rejectReason = rawReason;
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT employee_id AS "employeeId", status AS "status"
         FROM education_application
         WHERE education_application_id = CAST(:id AS bigint)
         FOR UPDATE`,
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'EDUCATION_APPLICATION_NOT_FOUND', '교육신청을 찾을 수 없습니다.');
      }
      const current = found[0];
      if (current.status !== '신청') {
        throw new ApiError(409, 'EDUCATION_APPLICATION_STATE_CONFLICT', '신청 상태인 건만 반려할 수 있습니다.');
      }
      const rows = await db.query(
        `UPDATE education_application
         SET status = '반려', reject_reason = :rejectReason, updated_at = now()
         WHERE education_application_id = CAST(:id AS bigint)
         RETURNING education_application_id AS "educationApplicationId", status AS "status"`,
        { id, rejectReason },
      );
      await db.execute(
        `INSERT INTO notification
           (recipient_id, channel, title, content, read_status, event_type, target_type, target_id, created_at, updated_at)
         VALUES
           (CAST(:recipientId AS bigint), :channel, :title, :content, '안읽음', 'EDUCATION_APPLICATION_REJECTED',
            'EDUCATION_APPLICATION', CAST(:id AS bigint), now(), now())`,
        {
          recipientId: String(current.employeeId),
          channel: DEFAULT_CHANNEL,
          title: '교육신청이 반려되었습니다.',
          content: rejectReason,
          id,
        },
      );
      return rows[0];
    });
  }

  @Post('/education-applications/:educationApplicationId/cancel-approval')
  @HttpCode(200)
  async cancelEducationApplicationApproval(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자');
    const id = pathId(req.params['educationApplicationId']);
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT status AS "status"
         FROM education_application
         WHERE education_application_id = CAST(:id AS bigint)
         FOR UPDATE`,
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'EDUCATION_APPLICATION_NOT_FOUND', '교육신청을 찾을 수 없습니다.');
      }
      if (found[0].status !== '승인') {
        throw new ApiError(409, 'EDUCATION_APPLICATION_STATE_CONFLICT', '승인 상태인 건만 승인 취소할 수 있습니다.');
      }
      const rows = await db.query(
        `UPDATE education_application
         SET status = '승인 취소', updated_at = now()
         WHERE education_application_id = CAST(:id AS bigint)
         RETURNING education_application_id AS "educationApplicationId", status AS "status"`,
        { id },
      );
      await db.execute(
        `INSERT INTO change_history
           (changer_id, target_type, target_id, change_type, changed_at, change_content, created_at, updated_at)
         VALUES
           (CAST(:userId AS bigint), 'education_application', CAST(:id AS bigint), '승인 취소', now(),
            '교육신청 상태를 승인에서 승인 취소로 변경', now(), now())`,
        { userId: user.id, id },
      );
      return rows[0];
    });
  }

  @Delete('/education-applications/:educationApplicationId')
  async deleteEducationApplication(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const id = pathId(req.params['educationApplicationId']);
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT status AS "status"
         FROM education_application
         WHERE education_application_id = CAST(:id AS bigint)
         FOR UPDATE`,
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'EDUCATION_APPLICATION_NOT_FOUND', '교육신청을 찾을 수 없습니다.');
      }
      if (found[0].status === '승인') {
        throw new ApiError(409, 'EDUCATION_APPLICATION_APPROVED', '승인된 신청은 삭제할 수 없습니다. 승인 취소 절차를 거쳐 주세요.');
      }
      await db.execute(
        'DELETE FROM education_application WHERE education_application_id = CAST(:id AS bigint)',
        { id },
      );
      return {};
    });
  }
}

