import { useState } from 'react';
import { Badge, Band, DataTable, Drawer, Field, Form, LookupSelect, RefName, TextInput, call } from '../kit';
import type { PageProps } from '../kit';

type Item = {
  id: number;
  sessionId: number;
  reason: string;
  status: string;
};

type Mode =
  | { kind: 'create' }
  | { kind: 'approve' | 'reject' | 'cancel' | 'delete'; item: Item }
  | null;

type Result = { educationApplicationId: number; status: string };

export default function FnSfr01503Page({ role, notify }: PageProps) {
  const [items, setItems] = useState<Item[]>([]);
  const [mode, setMode] = useState<Mode>(null);
  const [sessionId, setSessionId] = useState<number | string>('');
  const [applicationReason, setApplicationReason] = useState('');
  const [rejectReason, setRejectReason] = useState('');

  const close = () => {
    setMode(null);
    setSessionId('');
    setApplicationReason('');
    setRejectReason('');
  };

  const setStatus = (id: number, status: string) => {
    setItems((prev) => prev.map((x) => (x.id === id ? { ...x, status } : x)));
  };

  const create = async () => {
    if (sessionId === '') {
      throw new Error('교육차수를 선택해 주세요.');
    }
    const result = await call<Result>('POST', '/education-applications', role, {
      educationSessionId: sessionId,
      applicationReason,
    });
    setItems((prev) => [
      {
        id: result.educationApplicationId,
        sessionId: Number(sessionId),
        reason: applicationReason,
        status: result.status,
      },
      ...prev,
    ]);
    notify('교육을 신청했습니다.');
    close();
  };

  const approve = async (item: Item) => {
    const result = await call<Result>('POST', '/education-applications/' + item.id + '/approve', role, {});
    setStatus(item.id, result.status);
    notify('교육신청을 승인했습니다.');
    close();
  };

  const reject = async (item: Item) => {
    if (rejectReason.trim() === '') {
      throw new Error('반려 사유를 입력해 주세요.');
    }
    const result = await call<Result>('POST', '/education-applications/' + item.id + '/reject', role, {
      rejectReason,
    });
    setStatus(item.id, result.status);
    notify('교육신청을 반려했습니다.');
    close();
  };

  const cancelApproval = async (item: Item) => {
    const result = await call<Result>('POST', '/education-applications/' + item.id + '/cancel-approval', role, {});
    setStatus(item.id, result.status);
    notify('승인을 취소했습니다.');
    close();
  };

  const remove = async (item: Item) => {
    await call('DELETE', '/education-applications/' + item.id, role);
    setItems((prev) => prev.filter((x) => x.id !== item.id));
    notify('교육신청을 삭제했습니다.');
    close();
  };

  const columns = [
    { key: 'id', label: '교육신청 ID' },
    {
      key: 'sessionId',
      label: '교육차수',
      render: (row: Item) => <RefName table="education_session" role={role} value={row.sessionId} />,
    },
    { key: 'reason', label: '신청 사유' },
    { key: 'status', label: '처리 상태', render: (row: Item) => <Badge value={row.status} /> },
    {
      key: 'actions',
      label: '처리',
      render: (row: Item) => (
        <span>
          {row.status === '신청' && (
            <button className="ghost" onClick={() => setMode({ kind: 'approve', item: row })}>
              승인
            </button>
          )}
          {row.status === '신청' && (
            <button className="ghost" onClick={() => setMode({ kind: 'reject', item: row })}>
              반려
            </button>
          )}
          {row.status === '승인' && (
            <button className="ghost" onClick={() => setMode({ kind: 'cancel', item: row })}>
              승인 취소
            </button>
          )}
          {row.status !== '승인' && (
            <button className="ghost" onClick={() => setMode({ kind: 'delete', item: row })}>
              삭제
            </button>
          )}
        </span>
      ),
    },
  ];

  return (
    <div>
      <Band total={items.length}>
        <button onClick={() => setMode({ kind: 'create' })}>교육 신청</button>
      </Band>
      <DataTable<Item>
        columns={columns}
        rows={items}
        empty="아직 처리한 교육신청이 없습니다. 교육 신청 버튼으로 신청해 주세요."
      />
      {mode && mode.kind === 'create' && (
        <Drawer title="교육 신청" onClose={close}>
          <Form onSubmit={create} submit="신청">
            <Field label="교육차수" required>
              <LookupSelect
                table="education_session"
                role={role}
                value={sessionId}
                onChange={setSessionId}
                placeholder="교육차수 선택"
              />
            </Field>
            <Field label="신청 사유" wide>
              <TextInput value={applicationReason} onChange={setApplicationReason} multiline />
            </Field>
          </Form>
        </Drawer>
      )}
      {mode && mode.kind === 'approve' && (
        <Drawer title="교육신청 승인" onClose={close}>
          <Form
            onSubmit={() => approve(mode.item)}
            submit="승인"
            note="승인하면 신청자가 해당 차수의 교육대상자로 반영되고 신청자에게 알림이 갑니다."
          />
        </Drawer>
      )}
      {mode && mode.kind === 'reject' && (
        <Drawer title="교육신청 반려" onClose={close}>
          <Form onSubmit={() => reject(mode.item)} submit="반려" danger>
            <Field label="반려 사유" required wide>
              <TextInput value={rejectReason} onChange={setRejectReason} multiline />
            </Field>
          </Form>
        </Drawer>
      )}
      {mode && mode.kind === 'cancel' && (
        <Drawer title="승인 취소" onClose={close}>
          <Form
            onSubmit={() => cancelApproval(mode.item)}
            submit="승인 취소"
            danger
            note="승인을 취소하면 변경 이력이 남습니다."
          />
        </Drawer>
      )}
      {mode && mode.kind === 'delete' && (
        <Drawer title="교육신청 삭제" onClose={close}>
          <Form
            onSubmit={() => remove(mode.item)}
            submit="삭제"
            danger
            note="삭제한 교육신청은 되돌릴 수 없습니다."
          />
        </Drawer>
      )}
    </div>
  );
}
